<script setup lang="ts">
import {useReadFeedback} from '@/ui/useReadFeedback';
import {computed,ref,watch,onBeforeUnmount} from 'vue';import {useSessionStore} from '@/session/store';import {myProjects} from '@/native/discovery.mjs';import {readProjects} from '@/native/hub-data';import {captureApiLease} from '@/api/client';import AppIcon from './AppIcon.vue';
const {error,feedback}=useReadFeedback({retry:()=>load(),ready:()=>useSessionStore().businessReady});
const session=useSessionStore(),projects=ref<any[]>([]),busy=ref(false),expanded=ref({personal:false,team:false});let alive=true;
const groups=computed(()=>[{key:'personal' as const,title:'个人项目',items:projects.value.filter(p=>p.visibility!=='team')},{key:'team' as const,title:'团队项目',items:projects.value.filter(p=>p.visibility==='team')}]);
const stateKey=()=> 'qn.project-groups-v1:'+session.user?.username;
function restore(){expanded.value={personal:false,team:false};try{const saved=JSON.parse(localStorage.getItem(stateKey())||'null');if(saved)expanded.value={personal:saved.personal===true,team:saved.team===true};}catch{}}
function toggle(key:'personal'|'team'){expanded.value[key]=!expanded.value[key];try{localStorage.setItem(stateKey(),JSON.stringify(expanded.value));}catch{}}
async function load(force=false){if(busy.value)return;const lease=captureApiLease();if(!lease.account)return;busy.value=true;feedback.begin(projects.value.length>0);const apply=(list:any[])=>{if(alive&&lease.valid()){projects.value=myProjects(list,lease.account);feedback.begin(true);}};try{apply(await readProjects(lease,{force,onSnapshot:apply}));if(lease.valid())feedback.succeeded();}catch(e){if(alive&&lease.valid()){feedback.failed(e,'项目暂未更新，请重试');if([401,403].includes((e as any)?.status))projects.value=[];}}finally{if(alive&&lease.valid())busy.value=false;}}
watch(()=>session.businessReady,ready=>{if(ready)void load();});
watch(()=>session.user?.username,()=>{feedback.succeeded();projects.value=[];restore();void load();},{immediate:true});onBeforeUnmount(()=>{alive=false;});
</script>
<template><section class="my-projects"><h2>我的项目</h2><div class="project-group" v-for="group in groups" :key="group.key"><button class="group-heading" :aria-expanded="expanded[group.key]" :aria-controls="'my-projects-'+group.key" @click="toggle(group.key)"><AppIcon name="folder"/><span>{{group.title}}</span><small>{{group.items.length}}</small><AppIcon name="chevron" :class="{expanded:expanded[group.key]}"/></button><div class="project-collapse" :class="{open:expanded[group.key]}" :inert="!expanded[group.key]" :aria-hidden="!expanded[group.key]"><div :id="'my-projects-'+group.key" class="project-list"><RouterLink v-for="p in group.items" :key="p.project_id" class="project-entry" :to="{name:'work',query:{project:p.project_id}}"><span>{{p.title}}</span><AppIcon name="chevron"/></RouterLink><p v-if="!group.items.length" class="field-help">{{busy?'正在读取项目…':'暂无'+group.title}}</p></div></div></div><p v-if="error" class="error-text" role="alert">{{error}}<button class="btn small" @click="load(true)">重试</button></p></section></template>
<style scoped>
.my-projects{margin:18px 0}.my-projects h2{font-size:15px;font-weight:600;margin:0 0 10px}.project-group{background:var(--paper);border:1px solid var(--line);border-radius:10px;overflow:hidden;margin:8px 0}.group-heading{display:flex;align-items:center;gap:10px;width:100%;min-height:48px;padding:12px;border:0;background:transparent;text-align:left;color:var(--ink);font-size:15px}.group-heading>span{flex:1}.group-heading small{font-size:12px;color:var(--muted)}.group-heading>.icon{width:18px;height:18px;color:var(--muted);flex:none}.group-heading>.icon:last-child{transition:transform .2s}.group-heading>.icon.expanded{transform:rotate(90deg)}.project-collapse{display:grid;grid-template-rows:0fr;transition:grid-template-rows .22s ease}.project-collapse.open{grid-template-rows:1fr}.project-list{min-height:0;overflow:hidden}.project-list>p{padding:10px 12px;margin:0}.project-entry{display:flex;align-items:center;gap:8px;min-height:44px;padding:10px 12px 10px 40px;color:var(--ink);font-size:14px;border-top:1px solid var(--line)}.project-entry>span{flex:1;min-width:0;overflow-wrap:anywhere}.project-entry>.icon{width:15px;flex:none;color:var(--muted)}@media(prefers-reduced-motion:reduce){.project-collapse,.group-heading>.icon:last-child{transition:none}}
</style>
